532:   /* ------------------------------------------------------------
533:      Hotspots, walking & interaction
534:      ------------------------------------------------------------ */
535:   function activeHotspots() {
536:     const sc = currentScene();
537:     if (!sc) return [];
538:     return sc.hotspots.filter((h) => !h.cond || h.cond(S));
539:   }
540: 
541:   function blockedAt(x, y, pad) {
542:     const sc = currentScene();
543:     if (!sc) return false;
544:     pad = pad == null ? 10 : pad;
545:     for (let i = 0; i < sc.blockers.length; i++) {
546:       if (U.pointInRect(sc.blockers[i], x, y, pad)) return true;
547:     }
548:     return false;
549:   }
550: 
551:   function hotspotApproach(h) {
552:     const sc = currentScene();
553:     if (!sc || !S) return { x: h.x, y: h.y };
554:     const walk = sc.walk;
555:     const r = h.r || 70;
556:     const radii = [r + 24, r + 58, r + 100, r + 150, r + 210];
557:     let best = null;
558:     let bestD = Infinity;
559:     for (let ri = 0; ri < radii.length; ri++) {
560:       const rad = radii[ri];
561:       for (let i = 0; i < 20; i++) {
562:         const a = (i / 20) * TAU;
563:         const x = clamp(h.x + Math.cos(a) * rad, walk.x + 18, walk.x + walk.w - 18);
564:         const y = clamp(h.y + Math.sin(a) * rad, walk.y + 18, walk.y + walk.h - 18);
565:         if (blockedAt(x, y, 12)) continue;
566:         const d = dist(S.player.x, S.player.y, x, y);
567:         if (d < bestD) {
568:           bestD = d;
569:           best = { x, y };
570:         }
571:       }
572:     }
573:     if (best) return best;
574:     return {
575:       x: clamp(h.x, walk.x + 18, walk.x + walk.w - 18),
576:       y: clamp(h.y, walk.y + 18, walk.y + walk.h - 18),
577:     };
578:   }
579: 
580:   function nearestHotspot() {
581:     const list = activeHotspots();
582:     let best = null;
583:     let bestD = Infinity;
584:     let bestAp = null;
585:     for (let i = 0; i < list.length; i++) {
586:       const h = list[i];
587:       const ap = hotspotApproach(h);
588:       const d = Math.min(dist(S.player.x, S.player.y, ap.x, ap.y), dist(S.player.x, S.player.y, h.x, h.y));
589:       if (d < bestD) {
590:         bestD = d;
591:         best = h;
592:         bestAp = ap;
593:       }
594:     }
595:     return bestD < 72 ? { h: best, ap: bestAp } : null;
596:   }
