618:   function interactWith(h) {
619:     if (!h || !S) return;
620:     const ap = hotspotApproach(h);
621:     const closeEnough = dist(S.player.x, S.player.y, ap.x, ap.y) < 72 || dist(S.player.x, S.player.y, h.x, h.y) < 76;
622:     if (closeEnough) {
623:       doAction(h);
624:     } else {
625:       walkTarget = { x: ap.x, y: ap.y };
626:       pendingHotspot = h;
627:       hide($('prompt'));
628:     }
629:   }
