631:   function tapAt(sx, sy) {
632:     if (!S) return;
633:     const wx = sx / cam.scale + cam.x;
634:     const wy = sy / cam.scale + cam.y;
635:     const list = activeHotspots();
636:     for (let i = 0; i < list.length; i++) {
637:       const h = list[i];
638:       const rr = Math.max(32, (h.r || 70) * 0.95);
639:       if (dist(wx, wy, h.x, h.y) < rr) {
640:         interactWith(h);
641:         return;
642:       }
643:     }
644:     const walk = currentScene().walk;
645:     if (!U.pointInRect(walk, wx, wy, 0)) return;
646:     let tx = clamp(wx, walk.x + 14, walk.x + walk.w - 14);
647:     let ty = clamp(wy, walk.y + 14, walk.y + walk.h - 14);
648:     if (blockedAt(tx, ty, 11)) {
649:       let found = false;
650:       for (let rad = 24; rad <= 140 && !found; rad += 22) {
651:         for (let i = 0; i < 16 && !found; i++) {
652:           const a = (i / 16) * TAU;
653:           const nx = clamp(tx + Math.cos(a) * rad, walk.x + 14, walk.x + walk.w - 14);
654:           const ny = clamp(ty + Math.sin(a) * rad, walk.y + 14, walk.y + walk.h - 14);
655:           if (!blockedAt(nx, ny, 11)) {
656:             tx = nx;
657:             ty = ny;
658:             found = true;
659:           }
660:         }
661:       }
662:     }
663:     walkTarget = { x: tx, y: ty };
664:     pendingHotspot = null;
665:   }
666: 
667:   function movePlayer(dx, dy) {
668:     if (!S) return;
669:     const sc = currentScene();
670:     const walk = sc.walk;
671:     const p = S.player;
672:     const nx = clamp(p.x + dx, walk.x + 12, walk.x + walk.w - 12);
673:     if (!blockedAt(nx, p.y, 10)) p.x = nx;
674:     const ny = clamp(p.y + dy, walk.y + 12, walk.y + walk.h - 12);
675:     if (!blockedAt(p.x, ny, 10)) p.y = ny;
676:   }
677: 
678:   function faceVector(dx, dy) {
679:     if (Math.abs(dx) > Math.abs(dy)) return dx < 0 ? 'left' : 'right';
680:     return dy < 0 ? 'up' : 'down';
681:   }
682: 
683:   function update(dt) {
684:     if (!S) return;
685:     S.playtime += dt;
686:     const sc = currentScene();
687:     let vx = 0;
688:     let vy = 0;
689: 
690:     if (keys['w'] || keys['arrowup']) vy -= 1;
691:     if (keys['s'] || keys['arrowdown']) vy += 1;
692:     if (keys['a'] || keys['arrowleft']) vx -= 1;
693:     if (keys['d'] || keys['arrowright']) vx += 1;
694: 
695:     if (joystickVec && Math.hypot(joystickVec.x, joystickVec.y) > 0.16) {
696:       vx = joystickVec.x;
697:       vy = joystickVec.y;
698:     }
699: 
700:     if (vx || vy) {
701:       walkTarget = null;
702:       pendingHotspot = null;
703:       const len = Math.hypot(vx, vy) || 1;
704:       const nx = vx / len;
705:       const ny = vy / len;
706:       S.player.dir = faceVector(nx, ny);
707:       movePlayer(nx * 178 * dt, ny * 178 * dt);
708:       playerWalking = true;
709:       playerPhase += dt * 9.4;
710:       stepClock -= dt;
711:       if (stepClock <= 0) {
712:         AUDIO.step(sc.surface);
713:         stepClock = 0.35;
714:       }
715:     } else if (walkTarget) {
716:       const dx = walkTarget.x - S.player.x;
717:       const dy = walkTarget.y - S.player.y;
718:       const d = Math.hypot(dx, dy);
719:       if (d < 5) {
720:         S.player.x = walkTarget.x;
721:         S.player.y = walkTarget.y;
722:         walkTarget = null;
723:         playerWalking = false;
724:         if (pendingHotspot) {
725:           const h = pendingHotspot;
726:           pendingHotspot = null;
727:           doAction(h);
728:         }
729:       } else {
730:         S.player.dir = faceVector(dx, dy);
731:         movePlayer((dx / d) * 178 * dt, (dy / d) * 178 * dt);
732:         playerWalking = true;
733:         playerPhase += dt * 9.4;
734:         stepClock -= dt;
735:         if (stepClock <= 0) {
736:           AUDIO.step(sc.surface);
737:           stepClock = 0.35;
738:         }
739:       }
740:     } else {
741:       playerWalking = false;
742:       stepClock = 0;
743:     }
744: 
745:     updateCamera(dt, false);
746: 
747:     autosaveClock += dt;
748:     if (autosaveClock > 22) {
749:       autosaveClock = 0;
750:       saveNow(false);
751:     }
752:   }
