1712:       }
1713:       S.deductions[conn.id] = true;
1714:       selectedCards = [];
1715:       saveNow(false);
1716:       AUDIO.play('chime');
1717:       toast('A thread tied', conn.title, '✦');
1718:       renderBoard();
1719:       checkReady();
1720:       if (conn.core && D.coreDeductions(S) >= 4) {
1721:         setTimeout(() => {
1722:           if (S && !S.ending) toast('The whole story', 'The counter is waiting. Decide what should happen to the watch.', '✓');
1723:         }, 900);
1724:       }
1725:       return;
1726:     }
1727:     selectedCards = [];
1728:     AUDIO.play('wrong');
1729:     $('boardInstruction').textContent = 'Nothing connects those. Not yet.';
1730:     $$('.clue-card').forEach((el) => el.classList.add('wrong'));
