359: .clue-card.dragging{cursor:grabbing;box-shadow:0 18px 40px rgba(0,0,0,.55);z-index:5;transform:translate(-50%,-50%) scale(1.04)}
360: .clue-card .cc-kicker{font-size:6.5px;letter-spacing:.17em;text-transform:uppercase;color:#967b4e;margin-top:3px}
361: .clue-card .cc-title{font-family:var(--serif);font-size:15.5px;line-height:1.12;color:#31291d;margin-top:3px}
362: .clue-card .cc-sub{font-size:8.5px;line-height:1.3;color:#7d6c51;margin-top:4px}
