364: @keyframes wrongShake{0%,100%{margin-left:0}20%{margin-left:-6px}40%{margin-left:6px}60%{margin-left:-4px}80%{margin-left:4px}}
365: .board-side{width:290px;flex:none;padding:20px 22px;border-left:1px solid rgba(200,164,102,.12);overflow-y:auto;scrollbar-width:thin}
