396: /* decor */
397: .decor-frame{width:min(860px,94vw);max-height:92vh;background:linear-gradient(160deg,#eee1c9,#e0cfb0);border:1px solid rgba(200,164,102,.5);
398:   box-shadow:var(--shadow);display:flex;flex-direction:column;overflow:hidden}
399: .decor-body{padding:4px 30px 10px;overflow-y:auto;display:grid;grid-template-columns:1fr 1fr;gap:22px 28px}
400: .decor-cat h3{font-family:var(--serif);font-size:22px;color:#2f281d;line-height:1.1}
401: .decor-cat .decor-cat-sub{font-size:8px;letter-spacing:.17em;text-transform:uppercase;color:var(--gold-dim);margin:3px 0 10px}
402: .decor-options{display:flex;flex-direction:column;gap:6px}
403: .decor-option{display:flex;align-items:center;gap:11px;text-align:left;padding:9px 11px;border:1px solid rgba(93,75,45,.16);
404:   background:rgba(255,252,242,.24);transition:.18s;position:relative}
405: .decor-option:hover:not(:disabled){background:rgba(255,252,242,.58);border-color:rgba(200,164,102,.65);transform:translateX(2px)}
406: .decor-option.selected{border-color:var(--amber-soft);background:rgba(200,164,102,.16)}
407: .decor-option:disabled{opacity:.48;cursor:not-allowed}
408: .decor-swatch{width:26px;height:26px;flex:none;border-radius:50%;border:1px solid rgba(50,38,22,.25);box-shadow:inset 0 0 8px rgba(255,255,255,.35)}
409: .decor-option .do-name{font-family:var(--serif);font-size:16px;color:#332b1f;line-height:1.1;display:block}
410: .decor-option .do-desc{font-size:10px;line-height:1.35;color:#7b6b51;display:block;margin-top:2px}
411: .decor-option .do-check{position:absolute;right:10px;top:50%;transform:translateY(-50%);color:var(--gold-dim);font-size:14px}
412: .decor-foot{padding:12px 30px 22px;border-top:1px solid rgba(93,75,45,.12);font-family:var(--serif);font-style:italic;font-size:13px;color:#8a795d}
