426: /* settings */
427: .settings-frame{width:min(620px,94vw);max-height:92vh;background:linear-gradient(160deg,#eee1c9,#e0cfb0);border:1px solid rgba(200,164,102,.5);
428:   box-shadow:var(--shadow);display:flex;flex-direction:column;overflow:hidden}
