430: .slider-row{display:grid;grid-template-columns:120px 1fr 48px;align-items:center;gap:14px;padding:12px 0;border-bottom:1px solid rgba(93,75,45,.12)}
431: .slider-row span{font-size:11px;letter-spacing:.08em;color:#4b3f2e}
432: .slider-row output{font-size:10px;color:#8a795d;text-align:right}
433: input[type=range]{-webkit-appearance:none;appearance:none;height:2px;background:rgba(93,75,45,.25);outline:none}
434: input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:13px;height:13px;border-radius:50%;background:var(--amber-soft);
435:   border:2px solid #efe3cd;box-shadow:0 1px 5px rgba(0,0,0,.3);cursor:pointer}
436: input[type=range]::-moz-range-thumb{width:11px;height:11px;border-radius:50%;background:var(--amber-soft);border:2px solid #efe3cd;cursor:pointer}
