1893:   function paintEnding(which) {
1894:     const c = $('endingCanvas');
1895:     const g = c.getContext('2d');
1896:     const W = 1280;
1897:     const H = 800;
1898:     g.setTransform(1, 0, 0, 1, 0, 0);
1899:     g.clearRect(0, 0, W, H);
1900:     const id = which === 'returned' ? 'station' : 'shop';
1901:     const src = getSceneCanvas(id);
1902:     const sw = id === 'station' ? 1900 : 1500;
1903:     const sh = 1000;
1904:     const sc = Math.max(W / sw, H / sh);
1905:     const ox = (W - sw * sc) / 2;
1906:     const oy = (H - sh * sc) / 2;
1907:     g.drawImage(src, ox, oy, sw * sc, sh * sc);
1908: 
1909:     if (which === 'returned') {
1910:       g.save();
1911:       g.translate(ox, oy);
1912:       g.scale(sc, sc);
1913:       A.glow(g, 1390, 590, 190, '255,198,122', 0.16);
1914:       A.drawCharacter(g, 'june', 1390, 645, 0, 'left', { sitting: true });
1915:       g.restore();
1916:     } else {
1917:       g.save();
1918:       g.globalCompositeOperation = 'lighter';
1919:       A.glow(g, 1085, 575, 190, '255,196,120', 0.14);
1920:       g.restore();
1921:     }
1922: 
1923:     const wash = g.createLinearGradient(0, 0, W, 0);
1924:     wash.addColorStop(0, 'rgba(4,8,9,.74)');
1925:     wash.addColorStop(0.42, 'rgba(4,8,9,.38)');
1926:     wash.addColorStop(0.75, 'rgba(4,8,9,.06)');
1927:     wash.addColorStop(1, 'rgba(4,8,9,.3)');
1928:     g.fillStyle = wash;
1929:     g.fillRect(0, 0, W, H);
1930:     const vig = g.createRadialGradient(W * 0.62, H * 0.48, H * 0.15, W * 0.62, H * 0.48, H * 0.86);
1931:     vig.addColorStop(0, 'rgba(0,0,0,0)');
1932:     vig.addColorStop(1, 'rgba(0,0,0,.45)');
1933:     g.fillStyle = vig;
1934:     g.fillRect(0, 0, W, H);
1935:   }
