1262:   function inspectClick(e) {
1263:     if (!inspectState) return;
1264:     const c = $('inspectCanvas');
1265:     const rect = c.getBoundingClientRect();
1266:     const x = ((e.clientX - rect.left) / rect.width) * 900;
1267:     const y = ((e.clientY - rect.top) / rect.height) * 620;
1268:     const side = currentInspectSide();
1269:     let found = null;
1270:     let foundD = Infinity;
1271:     inspectState.obj.details.forEach((detail) => {
1272:       if (detail.side && detail.side !== side) return;
1273:       if (isDetailDiscovered(detail)) return;
1274:       const dx = detail.x * 900;
1275:       const dy = detail.y * 620;
1276:       const rr = Math.max(30, detail.r * Math.min(900, 620));
1277:       const d = dist(x, y, dx, dy);
1278:       if (d < rr && d < foundD) {
1279:         foundD = d;
1280:         found = detail;
1281:       }
1282:     });
1283:     if (found) discoverDetail(found);
1284:   }
