1286:   function renderInspect() {
1287:     if (!inspectState) return;
1288:     const c = $('inspectCanvas');
1289:     const g = c.getContext('2d');
1290:     const W = 900;
1291:     const H = 620;
1292:     if (inspectState.targetAngle != null) {
1293:       inspectState.angle = U.damp(inspectState.angle, inspectState.targetAngle, 12, dtGlobal);
1294:       if (Math.abs(inspectState.angle - inspectState.targetAngle) < 0.008) {
1295:         inspectState.angle = inspectState.targetAngle;
1296:         inspectState.targetAngle = null;
1297:       }
1298:     }
1299:     g.setTransform(1.5, 0, 0, 1.5, 0, 0);
1300:     g.clearRect(0, 0, W, H);
1301:     A.drawObject(g, inspectState.obj.id, W, H, { angle: inspectState.angle, t: tGlobal });
1302:     const side = currentInspectSide();
1303:     inspectState.obj.details.forEach((detail) => {
1304:       if (detail.side && detail.side !== side) return;
1305:       if (isDetailDiscovered(detail)) return;
1306:       const x = detail.x * W;
1307:       const y = detail.y * H;
1308:       const pulse = (Math.sin(tGlobal * 2.6 + detail.x * 9 + detail.y * 7) + 1) / 2;
1309:       const rr = Math.max(18, detail.r * Math.min(W, H));
1310:       A.glow(g, x, y, rr * 2.4, '255,200,130', 0.12 + pulse * 0.08);
1311:       g.strokeStyle = 'rgba(255,220,168,' + (0.5 + pulse * 0.3) + ')';
1312:       g.lineWidth = 1.3;
1313:       g.beginPath();
1314:       g.arc(x, y, 9 + pulse * 3, 0, TAU);
1315:       g.stroke();
1316:       g.fillStyle = 'rgba(255,232,184,.9)';
1317:       g.beginPath();
1318:       g.arc(x, y, 2.4, 0, TAU);
1319:       g.fill();
1320:     });
1321:   }
